  'accounts.entrySubtitle': { ru: 'Баланс, загрузка и оплата по каждой карте', en: 'Balance, utilization and due dates per card', es: 'Saldo, uso y vencimientos por tarjeta', fr: 'Solde, utilisation et échéances par carte' },
